import fs from 'fs';
import path from 'path';
import dotenv from 'dotenv';
import pg from 'pg';

// Prioritize .env.local (generated by neon deploy / neon env pull), then fallback to .env
if (fs.existsSync('.env.local')) {
  dotenv.config({ path: '.env.local' });
}
dotenv.config();

const { Pool: PgPool } = pg;

let pooledPool = null;
let directPool = null;

/**
 * Initializes and returns the PostgreSQL connection pool.
 * Compatible with Neon Serverless Postgres.
 * @param {object} [options]
 * @param {boolean} [options.unpooled=false] - Whether to use the direct (unpooled) connection
 */
export function getPool(options = {}) {
  const { unpooled = false } = options;

  if (unpooled) {
    if (directPool) return directPool;
    const connectionString = process.env.DATABASE_URL_UNPOOLED || process.env.DATABASE_URL;
    if (!connectionString) {
      throw new Error(
        'Missing DATABASE_URL / DATABASE_URL_UNPOOLED environment variable.\n' +
        'Please run `neon deploy` or `neon env pull` to fetch your Neon credentials.'
      );
    }
    directPool = new PgPool({
      connectionString,
      ssl: { rejectUnauthorized: false },
    });
    return directPool;
  }

  if (pooledPool) {
    return pooledPool;
  }

  const connectionString = process.env.DATABASE_URL || process.env.DATABASE_URL_UNPOOLED;

  if (!connectionString) {
    throw new Error(
      'Missing DATABASE_URL environment variable.\n' +
      'Please run `neon deploy` or `neon env pull` to fetch your Neon credentials.'
    );
  }

  // Use pg.Pool with SSL enabled for robust connection to Neon
  pooledPool = new PgPool({
    connectionString,
    ssl: { rejectUnauthorized: false },
  });

  return pooledPool;
}

/**
 * Executes a parameterized SQL query.
 * @param {string} text - SQL query string
 * @param {Array<any>} [params] - Query parameters
 * @param {object} [options] - Options (e.g. { unpooled: true })
 * @returns {Promise<pg.QueryResult>}
 */
export async function query(text, params = [], options = {}) {
  const p = getPool(options);
  return await p.query(text, params);
}

/**
 * Executes a query specifically using the direct unpooled connection (best practice for DDL/migrations).
 */
export async function queryDirect(text, params = []) {
  return await query(text, params, { unpooled: true });
}

/**
 * Closes all open connection pools.
 */
export async function closePool() {
  if (pooledPool) {
    await pooledPool.end();
    pooledPool = null;
  }
  if (directPool) {
    await directPool.end();
    directPool = null;
  }
}

/**
 * Verifies connectivity to the database.
 * @returns {Promise<{ ok: boolean, version?: string, error?: string }>}
 */
export async function checkConnection() {
  try {
    const res = await query('SELECT version(), current_database() as database_name');
    const info = {
      ok: true,
      database: res.rows[0].database_name,
      version: res.rows[0].version,
      branch: process.env.NEON_BRANCH || 'unknown',
    };
    console.log('✅ Successfully connected to Neon Postgres:', info);
    return info;
  } catch (err) {
    console.error('❌ Database connection check failed:', err.message);
    return {
      ok: false,
      error: err.message,
    };
  }
}

export default {
  getPool,
  query,
  queryDirect,
  closePool,
  checkConnection,
};
